#include <stdio.h>
#include <stdlib.h>

#define MAX_N 64

static long value[MAX_N];
static int next[MAX_N];
static int head = -1; // index of first element in sorted list, -1 if empty
static int used = 0; // number of elements stored

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    // Process up to MAX_N numbers from command line
    for (int i = 1; i < argc && used < MAX_N; ++i) {
        char *endptr;
        long v = strtol(argv[i], &endptr, 10);
        // Store the value
        int idx = used;
        value[idx] = v;
        next[idx] = -1;
        used++;
        // Insert into sorted linked list (ascending)
        if (head == -1 || value[head] > v) {
            // Insert at head
            next[idx] = head;
            head = idx;
        } else {
            // Find insertion point
            int cur = head;
            while (next[cur] != -1 && value[next[cur]] <= v) {
                cur = next[cur];
            }
            // Insert after cur
            next[idx] = next[cur];
            next[cur] = idx;
        }
    }
    // Print the sorted list
    if (head == -1) {
        puts("EMPTY");
        return 0;
    }
    int cur = head;
    int first = 1;
    while (cur != -1) {
        if (!first) {
            putchar(' ');
        }
        printf("%ld", value[cur]);
        first = 0;
        cur = next[cur];
    }
    putchar('\n');
    return 0;
}
